INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q94796398', 'Battle of Porédaka', 'The Battle of Porédaka (13 November 1896) was a minor engagement in which French colonial troops decisively defeated the last forces of the Imamate of Futa Jallon, after which Fouta Djallon was annexed into the French Colonial Empire.', 1896, 11, 3, NULL, NULL, NULL, 'day', '3 November 1896', 34, 'https://en.wikipedia.org/wiki/Battle_of_Por%C3%A9daka'),
  ('Q60750351', '1984 Guinean coup d''état', 'The 1984 Guinean coup d''état was the bloodless military coup that took place in Guinea on 3 April 1984, led by Colonel Lansana Conté. It led to the deposition of Prime Minister Louis Lansana Beavogui, who had held the office since 1972, and had been serving as interim president since 26 March, when longtime President Ahmed Sékou Touré died during an emergency heart operation at the Cleveland Clinic in the United States.', 1984, 4, 3, NULL, NULL, NULL, 'day', '3 April 1984', 41, 'https://en.wikipedia.org/wiki/1984_Guinean_coup_d''%C3%A9tat'),
  ('Q2282672', '2008 Guinean coup d''état', 'On 23 December 2008, a coup d''état occurred in Guinea, shortly after the death of long-time president Lansana Conté. A junta called the National Council for Democracy and Development (French: Conseil National de la Démocratie et du Development, CNDD), headed by Captain Moussa Dadis Camara, seized power and announced that it planned to rule the country for two years prior to a new presidential election.', 2008, 12, 23, NULL, NULL, NULL, 'day', '23 December 2008', 50, 'https://en.wikipedia.org/wiki/2008_Guinean_coup_d''%C3%A9tat'),
  ('Q2504556', '2009 Guinean protests', 'The 2009 Guinean protests were an opposition rally in Conakry, Guinea on 28 September 2009, with about 50,000 participants demonstrating against the junta government that came to power after the 2008 Guinean coup d''état in December. The protest march was fueled by the indication of junta leader Captain Moussa Dadis Camara that he would break his pledge to not run in the next presidential vote, due in January 2010.', 2009, 9, 28, NULL, NULL, NULL, 'day', '28 September 2009', 41, 'https://en.wikipedia.org/wiki/2009_Guinean_protests'),
  ('Q15989108', 'Western African Ebola virus epidemic', 'The 2013–2016 epidemic of Ebola virus disease, centered in West Africa, was the most widespread outbreak of the disease in history. It caused major loss of life and socioeconomic disruption in the region, mainly in Guinea, Liberia and Sierra Leone.', 2013, 12, NULL, 2016, 6, NULL, 'month', 'December 2013 – June 2016', 78, 'https://en.wikipedia.org/wiki/Western_African_Ebola_epidemic'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q108419092', '2021 Guinean coup d''état', 'On 5 September 2021, President of Guinea Alpha Condé was captured by the country''s armed forces in a coup d''état after gunfire in the capital, Conakry. Special forces commander Mamady Doumbouya released a broadcast on state television announcing the dissolution of the constitution and government.', 2021, 9, 5, NULL, NULL, NULL, 'day', '5 September 2021', 64, 'https://en.wikipedia.org/wiki/2021_Guinean_coup_d''%C3%A9tat'),
  ('Q126961247', '2024 West African floods', 'In 2024, heavy rainfall impacted several countries across West and Central Africa, including Nigeria, Chad, Niger, Mali, Guinea, Cameroon and Ghana. At least 1,500 were killed and more than a million were displaced.', 2024, NULL, NULL, NULL, NULL, NULL, 'year', '2024', 37, 'https://en.wikipedia.org/wiki/2024_West_African_floods');

